#pragma once
#include <algorithm>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace penta::runtime::help {
struct Entry {std::string_view names,summary,usage,details;};
inline const std::vector<Entry>& entries() {
    static const std::vector<Entry> data{
        // BEGIN ROADMAP EXTENSION HELP
        {"tensor|tensorvalues|tensorcoords|tensorinfo|nativetensors","Use complete fixed-shape native tensors of rank1..8.","tensor<2,3,4> T=tensor(0,[2,3,4]); tensor<H,2,2> Q=tensor(H.i,[2,2]);","Entries retain every real, complex, Pentarnion or immutable-algebra coefficient in column-major entry order. Runtime slices and copy-on-write assignments preserve shape/type/hash. Cached native callbacks support bounded scalar indexing and AD1/AD2/AD3, root/fit/optimization and ODE tensor states. Tensor products are explicitly entrywise; * does not imply contraction. Native input/output128 and ODE64 coordinate limits apply. See specs/typed_tensors_v0_2.txt and examples/native-tensors."},
        {"jacobianpattern|jacobiansparse","Inspect conservative compiler Jacobian sparsity and evaluate native values.","record pattern=jacobianpattern(residual);record J=jacobiansparse(residual,point,options(parameters=options(...)));","The checked AST derives complete-coordinate one-based CSR without executing the callback. Patterns include branch/control dependencies and retain numeric zeros. jacobiansparse uses cached analytic AD values, without threshold guessing or a compressed-seed coloring claim. Matrices/tensors and immutable algebra hashes preserve their complete layout within128 input/output coordinates. See specs/structural_derivatives_and_dae_v0_2.txt."},
        {"daestructure|daeinitialize","Analyze conditional DAE structure and compute local complete consistent initials.","record structure=daestructure(residual,t,y,yp);record initial=daeinitialize(residual,t,y,yp,options(parameters=options(...)));","Compiler incidence, native matching and canonical offsets report a structural index candidate, not a general nonlinear index proof. A regular locally conditioned index0/1 partition uses compiled state/time derivatives and damped Newton to find consistent y, yp and acceleration. Higher-index/singular/piecewise initialization rejects. General nonlinear initial-parameter sensitivities are not claimed. lineardaesolve separately covers bounded constant pencils through index3. See specs/structural_derivatives_and_dae_v0_2.txt."},
        {"daeanalyze|lineardaesolve","Analyze native residuals and solve bounded higher-index constant descriptor systems.","record info=daeanalyze(residual,time,y,yp);record simulation=lineardaesolve(E,A,forcing,y0,options(...));","Native residual/Jy/Jyp evidence distinguishes conditioned local index0/index1 under explicit fixed-rank assumptions. Constant regular real pencils through index3 use checked reduction, generated time jets and native IDAS; all original residuals remain checked. Consistent initialization and parameter probes retain hidden constraints. Pointwise ranks are not a global nonlinear index proof. See specs/higher_index_linear_dae_v0_2.txt."},
        {"pdeimplicit|pdeimplicitcoeff|pdeimplicitslice|pdeconverge","Solve native implicit/adaptive full-coordinate PDEs.","record f=pdeimplicit(reaction,domain,initial,options(diffusion=.1,boundary=\"dirichlet\"));","FD1/FD2 and triangle P1 retain complete real/algebra coordinates, generated local Jacobians, ordered/spatiotemporal coefficients and explicit mixed boundary data. pdeconverge reports successive-grid numerical estimates, not rigorous bounds. See specs/implicit_pde_v0_2.txt."},
        {"femsystem|femsystemplot|femevaluate|femadapt|meshadapt|femtime|femtimecoeff|femtimeslice|femmixed|femmixedplot","Solve nonlinear, transient and mixed-order native H1 finite elements.","record f=femsystem(reaction,mesh,options(order=3,...));","Separate APIs provide uniform P1..P4 algebra/vector fields, native curved2..5D geometry, mixed/tagged Robin data, transient consistent-mass implicit integration, high-order reference sampling, conforming local adaptation, and real-R2 mixed H1 orders with native quasilinear flux Jacobians. Read each versioned layout; ragged mixed fields are not one shared nodal grid. See specs/fem_system_v0_2.txt, fem_time_v0_2.txt and fem_mixed_v0_2.txt."},
        {"petscsolve|petscroot","Use optional native PETSc sparse/nonlinear backends.","record r=petscsolve(A,b,options(method=\"gmres\"));","The lazy real PETSc module coordinates CPU grants and checks actual residuals. petscroot uses a cached compiled residual/Jacobian. Explicit unsupported/dependency errors replace silent solver substitution. See specs/petsc_v0_2.txt."},
        {"meshclosest|meshprobe|meshslice|meshray|meshcontains|meshintersect","Query real meshes, full-coordinate fields and intersections.","record p=meshprobe(mesh,points); record cut=meshintersect(mesh1,mesh2);","Bounded BVH projection/ray/probe/slice queries retain face provenance and complete field coordinates. Closed real3D solid classification and triangle-mesh intersections report boundary/point/segment/coplanar overlap explicitly, with scaled tolerance semantics. No certified Boolean-solid claim is made. See specs/mesh_queries_v0_2.txt and mesh_intersections_v0_2.txt."},
        {"intrinsicgeometry|tensorcovariant|charttransition|chartatlas|atlasgeometry|atlastransition|codifferential|formlaplacian|formpullback","Compute native intrinsic tensors, atlas transitions and differential forms.","record a=intrinsicgeometry(metric,point,options(connection=connection,frame=frame));","Explicit dimensions/metric/connection/variance conventions retain curvature, torsion, covariant derivatives, moving frames and directed atlas transition paths. Variable metric form jets and native analytic map derivatives support Hodge/codifferential/Laplacian/pullback compositions. See specs/intrinsic_geometry_v0_2.txt, chart_atlas_v0_2.txt and form_pullback_v0_2.txt."},
        {"saveplottemplate|loadplottemplate|linkcamera|fieldprobe|fieldslice","Reuse styles, link3D cameras and inspect retained fields.","saveplottemplate(\"style.json\");loadplottemplate(\"style.json\");linkcamera([1,2]);","Data-only versioned styles retain all label/LaTeX flags without changing samples.3D camera links are separate from2D linkaxes. Field probes/slices interpolate only saved spatial data and retain1..64 coefficients. Native SVG/PDF use lazy mathematical vector typography with outlined SVG glyphs. See specs/plot_templates_and_queries_v0_2.txt."},
        {"bar|histplot","Draw filled native bars or histogram bins.","bar(x,y,options(width=.8,baseline=0));histplot(samples,edges);bar(histogram(samples,edges),options(density=1));","Unequal bin widths and signed bar endpoints remain exact. Density uses the histogram normalization; native2D meshes export through existing figure/PNG/SVG/PDF/subplot paths. Settings accept width in(0,1], baseline and density0/1. Bin/point/cancellation budgets apply."},
        {"filter|filterstate|filtfilt|butter|spectrogram|istft|cpsd|mscohere|peakprops","Use native signal filtering, time/frequency analysis and peak properties.","record spectrum=spectrogram(samples,options(...));","DF2T filtering and Butterworth coefficients, forward/reverse filtering, arbitrary-length Fourier/Welch transforms, reconstructible STFT, cross spectra/coherence and topographic peak prominence/width/subsample positions use the additive lazy science module. Read normalization, boundary and sampling assumptions in specs/signal_statistics_extensions_v0_2.txt."},
        {"distpdf|distcdf|distinv|distrand|bootstrap","Evaluate native distributions and dependence-aware bootstrap.","matrix p=distcdf(\"normal\",x);record b=bootstrap(samples,statistic,options(...));","Seventeen Boost distribution families have checked parameter/domains and explicit discrete quantile semantics. Random draws report explicit/session-derived seeds. Native fixed-shape statistic callbacks and moving/circular/stationary block resamples retain independent streams and shared CPU/work bounds. Legacy builtin-string bootstrap remains compatible. See specs/signal_statistics_extensions_v0_2.txt."},
        {"basins|lyapunovscan|branchplot","Explore native attraction basins, Lyapunov grids and refined branches.","record b=basins(model,initial_rows,options(...));branchplot(branch);","Finite-horizon clusters, escape/unresolved/failure regions, Lyapunov curves/heatmaps and longer/tighter verification produce candidate evidence. Automatic fold/Hopf/flip refinements link accepted markers to their source branch. See specs/discovery_workflows_v0_2.txt and continuation_refinement_v0_2.txt."},
        {"odemultistartfit|odeprofilefit|odefitbootstrap|pdemultistartfit|pdeprofilefit|pdefitbootstrap","Run checkpointed native solver refit ensembles.","record r=odemultistartfit(model,guesses,...,options(checkpoint=\"fits.json\"));","Native Ceres/inference scheduling shares CPU grants and atomic completed-task ledgers. ODE sensitivities and explicitly labelled PDE finite differences have distinct contracts; bootstrap/profile settings and data remain runtime values for unchanged compiled models. See specs/solver_refits_v0_2.txt."},
        {"predictionbands|propagateprediction|profileinterval|identifiability|coveragefit|structuralidentifiability","Report prediction uncertainty, identifiability and coverage evidence.","record bands=predictionbands(fit,options(...));","Known-noise Gaussian/lognormal/Student-t/Poisson models, future-observation/finite-grid simultaneous bands, native parameter ensembles, profile regions and independently generated dataset coverage have explicit assumptions. Exact affine-polynomial structural rank proofs are separate from practical multistart ambiguity and local covariance. See specs/inference_uncertainty_v0_2.txt."},
        {"evolve","Run native population search, checkpoints, islands and constrained finishing.","record r=evolve(objective,initial,options(checkpoint=\"search.json\",resume=1,...));","Version2 stores bounded numeric population/algorithm/RNG state without executable archive objects. Deterministic islands, integer-coordinate lattices, supported nonlinear constraints, distinct-basin native local refinement and supplied high-fidelity verification preserve bounds/constraints. Algorithm-specific exclusions remain explicit. See specs/evolution_sessions_v0_2.txt."},
        {"savearchive|loadarchive|archiveinfo|archiveartifact|migrateexperiment|experimentcatalog|catalogueentry|replayexperiment","Save typed research archives, query catalogues and explicitly replay.","savearchive(\"study.json\",result,options(...));record info=archiveinfo(\"study.json\");","Verified version2 adds bounded accepted source/import/RNG history, uniform scientific call/plot metadata, typed workspace snapshots and opt-in opaque artifacts. Loading executes nothing; explicit replay uses a fresh bounded session and captured import closure. v1 migration preserves the original document. Native binaries remain platform-tagged opaque data. See specs/research_archives_v0_2.txt."},
        {"cas|caspent|casdiff|cassubs|casreal|cascomplex|caspentnumeric|casmatrix|casmatmul|caslinsolve|casdet|cascode|casnumeric","Compute exact domain-aware ordered symbolic expressions.","record f=cas(\"sin(x)/x\",options(...));","The separate lazy CAS retains exact rational/domain snapshots, symbolic gamma, nonzero/positive assumptions, known/formal functions and chain rules, complex principal branches, central symbolic matrix equations and guarded native specialization. It never assumes associativity of Pentarnion products. See specs/domain_symbolics_v0_2.txt."},
        {"ndmatmul|ndsolve|ndinv|ndlu","Apply native batched N-D ordered products and real/complex LU operations.","record c=ndmatmul(a,b);record x=ndsolve(a,b);","Explicit axes/physical domains/shapes and singleton batch expansion remain checked. Real/complex pages reuse one rank/conditioning decomposition and independent residuals, with shared CPU/scratch bounds. Pentarnion products retain increasing inner-index order. See specs/batched_nd_products_v0_2.txt and nd_complex_linalg_v0_2.txt."},
        {"quantity|unitpow|unitconvert|unitvalues|unitinfo","Use exact SI dimensions, affine/log units and complete algebra magnitudes.","record length_q=unitpow(quantity(4,\"cm^2\"),1,2);","Rational dimensions, explicit absolute/delta temperatures, logarithmic references and real/complex/Pentarnion/native-element magnitudes have separate checked contracts. Ordered multiplication is retained and unsupported nonlinear dimensional operations reject. Equation-level unitcheck remains opt-in. See specs/physical_quantities_v0_2.txt."},
        {"odeadjoint|hybridadjoint","Compute native continuous adjoints, running/event costs and moving terminal jumps.","record a=odeadjoint(model,initial,options(objective=terminal,running_cost=running,...));","BDF/Adams use CVODES; ERK/ESDIRK use native ARKODE reverse integration with every accepted forward-step interpolant. The reported reverse_table states the continuous-adjoint table, including the bounded-abscissa ESDIRK reverse mapping. Hybrid event costs/saltation/transverse event times and simultaneous event priorities have explicit derivative contracts; nonsmooth/grazing ambiguity rejects. See specs/hybrid_saltation_v0_2.txt."},
        {"module_info|module_load","Inspect or explicitly preload a native numerical module.","record modules=module_info();module_load(\"science\");","A fixed catalogue controls absolute-path module loading and ABI checking. Inspection never loads a module. Studio has a shared Modules/Feature Rules browser, checked completion, static symbol/signature/source inspection and navigable retained error frames. See specs/editor_assistance_v0_2.txt."},
        {"export","Export a checked MATLAB or Python source bundle with explicit target adapters.","penta-export --target python --scientific-adapters input.p --output output_directory","Studio File/Export and the CLI export checked syntax trees. Supported subsets include ordered Pentarnion calculations, typed real/complex arrays, functions/records, native-fit/optimization adapters, graphs, sampled geometry, mechanics,1D PDEs and explicit BDF/mass/event/sensitivity/adjoint adapters. Unsupported source semantics reject with a source location before output publication. Actual target validation covers Python and MATLAB R2020a; no universal MATLAB/Python parity is promised. See specs/checked_export_v0_2.txt and examples/portable-scientific-exports."},
        // END ROADMAP EXTENSION HELP
        {"nativearrays|statecoord","Compile fixed-shape real, Pentarnion or native-algebra matrices.",R"(native function matrix<2,2> square(matrix<2,2> A){return A*A;} matrix<H,1,2> q=[H.one,H.i]; plot(s.t,statecoord(s.q,3));)","Native arrays retain explicit shapes, immutable entry definitions and all coefficients in AD1/AD2/AD3 and ODE callbacks. Source indexing is MATLAB one-based column-major; the real C ABI is row-major cells then entry coefficients. statecoord selects a zero-based full real coordinate from an array-state series. See specs/native_arrays_v0_2.txt and examples/native-array-callbacks."},
        {"masssolve","Solve time/state-dependent native mass operators with IDAS.",R"(record s=masssolve(rhs,mass,y0,yp0,options(t1=1,jacobian="analytic"));)","Solves M(t,y)*y'=f(t,y) without inverting a singular mass operator. Both source callbacks compile and cache natively; generated derivatives retain dM/dy*y'. Exact-zero initial mass columns select an algebraic mask, with local index-one validation and later partition-change rejection. This is not global index analysis. See specs/mass_operators_v0_2.txt and examples/state-dependent-mass."},
        {"mechanicsdae","Solve regular moving or velocity-constrained Lagrangian mechanics.",R"(record s=mechanicsdae(L,g,q0,v0,options(constraint_mode="position",jacobian="analytic"));)","Native AD2/AD3 constructs acceleration-level index-one residuals and analytic Jacobians for nonlinear masses, g(t,q)=0 or d'Alembert g(t,q,v)=0. Initial constraints must be consistent and the constrained block regular. Reports reaction forces, drift, energy/power/work and trapezoidal work error. See specs/general_constrained_mechanics_v0_2.txt."},
        {"unitcheck","Validate equation-level coherent SI dimensions.",R"(record u=unitcheck(oscillator,options(t="s",x="m",v="m/s",omega="s^-1"));)","Checks saved typed function/ODE expressions, homogeneous array/algebra coefficients and output/input derivative dimensions. ODE RHS units must equal state/time. Optional solver units annotations do not alter numeric values or cache identity. Zero literals are dimensionally polymorphic; transcendental arguments must be dimensionless. See specs/equation_units_v0_2.txt."},
        {"help|lookfor|topics","Find help for a command or language keyword.",R"(help plot; help("odesolve"); lookfor "sensitivity";)","help topics lists the catalogue. lookfor searches names and descriptions. A function name prints its typed signature. Names in command-style help are literal topics, not evaluated variables."},
        {"run","Run a saved script in the Studio Command Window.",R"(run main.p; run "folder/my script.p"; run("main.p");)","Relative paths use the project folder, or the current source folder outside a project. Dirty open scripts are saved before execution; save conflicts block execution. File runs replace the workspace. This is a Studio command; use penta-run path.p from a system terminal."},
        {"display","Print values without changing them.",R"(display("p =",p); display([1,100]);)","Arguments print in order in the same Command Window. Semicolons suppress automatic command-result echo, not display output."},
        {"clc|clear","Clear the transcript or workspace.","clc; clear; clear all; clear p q;","clc clears displayed output. clear removes variables, functions and model definitions; clear names removes selected bindings. These operations have distinct effects."},
        {"who|whos","Inspect workspace variables.","who; whos;","who lists names; whos includes types and shapes. Available after a file run and in the shared console workspace."},
        {"tic|toc","Measure execution wall time, excluding native compilation.","tic; ... toc; real seconds=toc();","tic restarts the session stopwatch. toc prints elapsed seconds; toc() returns them. Native compilation is excluded on cold and cached runs. A preceding tic is required."},
        {"use_algebra|gamma","Choose the normalized algebra context.",R"(use_algebra("A_gamma",gamma=1);)","Five coefficients use basis (1,i,j,k,ell). Algebra context is immutable for values; clear the existing command workspace before changing it. Parentheses and operand order remain significant."},
        {"algebras|algebra|element|builtin_algebra|import_algebra","Use native algebra families or a data-only multiplication table.",R"(algebra H=builtin_algebra("quaternion"); element<H> q=1+H.i+H.j; element p=element(H,[1,1,1,0]); algebra A=import_algebra("definition.json");)","Real/complex, quaternion/octonion/sedenion, dual/dual-quaternion, split/Clifford and matrix/Lie/Jordan presets retain immutable definitions and all real coefficients. H.i is distinct from legacy Pentarnion i. A real scalar embeds through the validated unit vector. Table imports require literal paths; import_algebra(metadata_json,products_csv_xlsx[,sheet]) accepts native numeric rows [left1,right1,output1,coefficient] with floating metadata and an empty products array. Imports execute neither source nor spreadsheet formulas. See NATIVE_ALGEBRAS_GUIDE.txt, specs/native_algebras_v0_2.txt and examples/native-algebras/project.pprj."},
        {"algebra_info|algebra_basis|algebra_coefficients|algebra_norm|algebra_json|algebra_products","Inspect a native algebra definition or complete element coordinates.",R"(record info=algebra_info(H); element e=algebra_basis(H,1); matrix c=algebra_coefficients(q); display(algebra_norm(q));)","Property evidence distinguishes exact proof, numerical checks, user declarations and unknown capabilities. coeff(q,index0) and algebra_basis use zero-based indices. algebra_norm is the Euclidean coordinate norm; norm2 requires an explicit positive metric and does not imply norm composition. Whole-element sin/cos/exp/sinh/cosh require a unit and exactly proved power associativity. algebra_json exports portable zero-based JSON; algebra_products exports one-based numeric sparse rows for native CSV/XLSX."},
        {"algebra_leftop|algebra_rightop|algebra_solveleft|algebra_solveright","Solve explicitly ordered native algebra equations with rank/residual safeguards.",R"(element x=solveleft(a,b); element y=solveright(a,b); record r=algebra_solveleft(a,b,options(condition_limit=1e12)); matrix L=algebra_leftop(a);)","solveleft solves a*x=b; solveright solves x*a=b. Real operator matrices act on coefficient columns. Reports provide has_solution,solution,status,rank,condition/availability and relative_residual/availability. Only an accepted unique equation solution is returned. inv(a) verifies a reciprocal and has a different contract, especially for sedenion zero divisors. Native compiled whole-element division/solve calls currently reject; native real scalar division remains supported."},
        {"pentarnion|integer|real|string|matrix|vector|realmatrix|pentarnionmatrix|record|tuple|callback|complex|logicalmatrix","Declare typed values.",R"(pentarnion p=1+i+j; real a=2.0; matrix A=[1,2;3,4]; record r=options(rate=2);)","Matrices/vectors have real or Pentarnion elements and bounded 2D shapes. Explicit complex scalars use complex(a,b), keeping imaginary units distinct from the algebra basis i. Records expose named fields; tuples support typed multiple outputs."},
        {"if|else|true|false","Conditional execution.","if(x>0){display(x);}else{display(0);}","Conditions are scalar real/integer truth values. && and || short-circuit. Array comparisons produce masks; use an explicit reduction for a scalar condition."},
        {"for|while|break|continue","Run bounded loops.","for(n=1:10){display(n);} while(x<10){x=x+1;}","for iterates real ranges/vectors. break exits a loop; continue advances it. Local declarations are scoped to the loop body. Operation and cancellation limits still apply."},
        {"function|return|void","Define a typed function.","function real square(real x){return x*x;}","Define functions before calling them. Parameters and locals are typed; multiple outputs use function [real a,real b] f(...){return ..., ...;}. General interpreted functions may use language control flow; native callbacks have a restricted pure numeric body."},
        {"compile_info","Inspect native compilation and structural cache reuse.","display(compile_info());","Reports requested/effective job limits, prepared translation_units, actual compiler_attempts, cache_hits, failed_preparations, peak_compiler_jobs and compilation_seconds. Peak compiler jobs is measured from overlapping compiler intervals. tic/toc excludes their union in wall time. Unchanged bodies, parameter-only edits and comment-only edits reuse cached libraries."},
        {"native","Compile a pure numerical callback to a cached DLL/SO.","native function real objective(real x){return (x-2)*(x-2);}","Solver callbacks compile natively even if their typed function lacks the native keyword. Supported bodies use real/Pentarnion scalar expressions, locals and branches. Structure, toolchain and ABI identify the cache; runtime parameters and solver settings do not. Multiple required translation units may compile concurrently within a bounded GCC job budget."},
        {"i|j|k|ell|basis","Canonical imaginary basis elements.","pentarnion p=1+i-j+0.5*k+ell;","The five real coordinates are ordered (1,i,j,k,ell). Basis products use normalized A_gamma_v1 rules. Preserve explicit parentheses for nonassociative products; the compiler diagnoses ambiguous multiplication chains."},
        {"pent|scalar|pure","Construct a Pentarnion or select its scalar/pure part.","pentarnion p=pent([1,2,3,4,5]); display(scalar(p),pure(p));","pent takes five real coefficients in (1,i,j,k,ell) order. scalar returns the scalar coefficient; pure removes that coefficient. coeff(p,n) selects component0..4."},
        {"realpart|imagpart|arg","Inspect an explicit complex scalar.","complex z=complex(1,2); display(realpart(z),imagpart(z),arg(z));","These operate on explicit complex values, keeping their imaginary part separate from the Pentarnion basis i. arg is the complex phase in radians."},
        {"import|as","Import saved source functions.",R"(import "helpers.p" as science;)","Imports resolve against source/project locations and preserve exact saved source dependencies. Module aliases avoid collisions. Import cycles and source budgets are checked."},
        {"options|with_options|get_option","Create and update named options.",R"(record cfg=options(method="bdf",rtol=1e-8); real r=get_option(cfg,"rtol");)","Pass options records as the final argument where documented. with_options(defaults,name=value,...) overrides known defaults with type checks. Unknown solver options are diagnosed."},
        {"indexing|end|range|linspace","Select entries or construct sample coordinates.","A(1:end); A(:,2); A(1:2:9); vector t=linspace(0,1,101);","Indexing is one-based, with column-major linear indices. end means the last index of its dimension. a:b and a:step:b are bounded real ranges; indexed writes cannot resize an array."},
        {"zeros|ones|eye|size|numel|length","Construct arrays and inspect shapes.","matrix Z=zeros(3,4); matrix I=eye(3); display(size(Z),numel(Z));","zeros/ones allocate real arrays; eye builds a real identity. Shape, element and retained-coordinate limits apply before allocation."},
        {"rand|randn|randi|rng","Generate reproducible random values.","rng(42); matrix U=rand(3,4); matrix N=randn(3,4);","rand is uniform, randn normal, randi bounded integer-valued. Explicit rng seeds reproduce the sequence. A cancelled request restores its prior random/workspace snapshot."},
        {"reshape|diag|transpose","Reshape arrays or select diagonal/transpose operations.","matrix B=reshape(A,2,[]); matrix D=diag([1,2,3]); matrix T=transpose(A);","Reshape preserves column-major indexing order and permits one inferred dimension. Transpose does not reverse the order inside Pentarnion products."},
        {"find|logical|meshgrid|ndgrid","Logical masks and coordinate grids.","matrix indices=find(A>0); logicalmatrix mask=logical(A);","find returns one-based selected indices. meshgrid/ndgrid return coordinate arrays through typed multiple outputs. Masks and grids remain bounded real arrays."},
        {"sum|mean|min|max","Reduce or compare real/Pentarnion arrays.","sum(A); mean(A,2); min(A,B); max(A,[],1);","Reductions use the first nonsingleton dimension unless selected. min/max require real orderable entries. Ordered Pentarnion sums retain the defined accumulation order. Per-call threads options may bound native work."},
        {"sin|cos|exp|sinh|cosh","Evaluate elementary functions.","pentarnion q=exp(p); vector y=sin(x);","Real inputs use ordinary real functions. Whole Pentarnion inputs use the paper's one-element calculus, not independent coefficient-wise trigonometry. Arrays apply the corresponding scalar function to each entry."},
        {"sqrt|tan|asin|acos|atan|atan2|tanh|asinh|acosh|atanh|log|log10|log2|floor|ceil|round|expm1|log1p|erf|erfc|hypot|sign","Basic real mathematical functions.","real y=log1p(0.01); real d=hypot(3,4);","Real domains and finite results are checked. Selected explicit complex-scalar functions are supported. Whole-Pentarnion extensions exist only where specified; unsupported algebra-valued calls are diagnosed."},
        {"coeff|conj|norm2|abs|inv|associator|commutator","Inspect and operate on algebra values.","real a=coeff(p,0); pentarnion c=conj(p); display(associator(p,q,r));","coeff uses canonical component indices 0..4. Scalar inv retains the algebra reciprocal. Real matrix inv is a native linear-algebra operation; Pentarnion matrix inverses require an explicitly selected left/right real operator."},
        {"dot|norm|axpy","Vector contractions and norms.",R"(real n=norm(A,"fro"); vector z=axpy(2,x,y);)","Use the documented real-coordinate norm conventions. Algebra-valued products preserve order; numeric thread options are maxima, not promises of multiple workers for small arrays."},
        {"threads|parallel_info","Control the coordinated CPU budget.","threads(0); threads(4); display(parallel_info());","0 selects automatic; 1..64 sets a maximum. options(threads=n) controls one call without changing the session. Nested numerical workers receive one inner slot. Actual host workers and configured backend limits are reported separately."},
        {"matmul|batchmul","Multiply arrays with ordered native products.","matrix C=matmul(A,B,options(threads=4)); matrix D=A*B;","Real products use native tiles/BLAS; Pentarnion products preserve binary operand order and increasing inner-index accumulation. batchmul accepts tuples of compatible matrix pairs; uniform batches use packed native dispatch."},
        {"det|lu|qr|chol|svd|eig|schur|rank|rcond|cond","Real dense linear algebra.","real d=det(A); record factors=svd(A); record e=eig(A);","LU uses P*A=L*U; pivoted QR uses A*P=Q*R; SVD uses A=U*S*V'. Complex eigendata is split into real/imaginary arrays. Whole-Pentarnion matrix determinant/inverse identities are not assumed."},
        {"linsolve|solve_report","Solve real linear equations or least-squares systems.",R"(matrix x=linsolve(A,b,options(method="qr")); record r=solve_report(A,b);)","Methods: lu, qr, cholesky, svd, subject to shape/rank requirements. Inspect residuals, conditioning and converged fields. A least-squares candidate need not solve an inconsistent equation exactly."},
        {"leftop|rightop|solveleft|solveright","Explicit Pentarnion left/right real-coordinate equations.","matrix L=leftop(A); matrix X=solveleft(A,B); matrix Y=solveright(A,B);","solveleft solves A*X=B; solveright solves X*A=B. Each Pentarnion contributes five ordered real coordinates. det(leftop(A)) describes that real operator; it does not define an associative algebra matrix determinant."},
        {"sparse|full|nnz|sparsemul|sparsetranspose|sparsesolve|sparse_solve_report","Sparse CSC storage and native sparse solves.","record S=sparse(A); matrix x=sparsesolve(S,b);","Canonical one-based CSC assembly combines duplicate entries and removes exact zeros. Products support real/Pentarnion data; native SparseLU/BiCGSTAB solves require real coordinate operators. Unavailable rank/condition estimates are explicitly marked."},
        {"jacobian|gradient|hessian|jvp|vjp|hvp|derivative_check","Native first/second derivatives and derivative products.","matrix H=hessian(objective,[1,2]); matrix v=hvp(objective,[1,2],[1,0]);","AD is analytic/default; finite_difference is explicit. Hessian/HVP require one real objective; HVP avoids constructing a full Hessian. ODE RHS state/parameter/time partials are distinct from integrated trajectory sensitivities. gradient also supports sampled data."},
        {"root|rootsolve|fixedpoint|equilibrium","Native scalar roots, square systems and equilibria.","record r=root(f,[0,2]); record q=rootsolve(F,[1,1]);","root uses bracketed TOMS748; rootsolve uses KINSOL newton/line_search. Native generated Jacobians or explicit finite differences apply. Always inspect converged/status/residual_norm; solver_failed with residual 1 in root-finding is the deliberate x*x+1 no-real-root example."},
        {"lsqfit|lsqnonlin|curvefit|odefit","Fit nonlinear real-coordinate residuals with Ceres.","record fit=lsqfit(residuals,initial,options(method=\"lm\")); curvefit(model,p0,xdata,ydata,options(...)); odefit(model,initial,times,observations,options(...));","Methods lm/dogleg; losses none/huber/soft_l1/cauchy. Options include lower/upper, parameter_scale, weights, parameters, max_iterations/max_evaluations/max_wall_seconds, starts/multistart/seed and explicit covariance. Callbacks compile to cached DLL/SO code; Pentarnion values flatten to five ordered real coefficients. ODE fitting uses CVODES trajectory sensitivities. Covariance requires stated local-linear/Gaussian assumptions. See examples/least-squares."},
        {"minimize","Optimize a native real objective with NLopt.","record result=minimize(objective,initial,options(algorithm=\"lbfgs\"));","Algorithms lbfgs, bobyqa, nelder_mead, slsqp, cobyla, direct, crs2, isres. Global algorithms require finite lower/upper bounds. Nonlinear inequality/equality callbacks require a supported constrained algorithm; inequalities mean c(x)<=0. All objective/constraint bodies are compiled native code. Inspect converged, feasible, constraint_violation, status and history. Set seed and evaluation/time budgets explicitly. Finite global searches do not certify a global optimum. See examples/optimization."},
        {"ode|odesolve|solution","Declare and solve an ODE with cached native RHS/Jacobian.",R"(ode decay(t,real y;real a){y'=-a*y;} solution s=odesolve(decay,y=1.0,a=2.0,t0=0,t1=5,method="bdf");)","Methods bdf/adams/erk/esdirk; jacobian analytic(default) or finite_difference. Access s.t and named states. Parameters, initials, tolerances and time bounds do not change the structural compilation cache. Advanced events/sensitivity controls are documented in advanced-odes."},
        {"odeevents|odesens|odestats|odewindow|odeadjoint","Advanced ODE events, sensitivity analysis and statistics.","record events=odeevents(s); matrix sens=odesens(s); record stats=odestats(s);","Native event callbacks support directed/terminal roots. CVODES integrates forward parameter/initial sensitivities and checkpointed terminal-objective adjoints. Dense evaluation uses retained integrator polynomials when available. Inspect method and combination restrictions. See examples/advanced-odes."},
        {"mapiterate|mapdiagram|returnmap","Native discrete map orbits and sampled orbit diagrams.","record orbit=mapiterate(map,initial,options(iterations=100));","Compiled maps preserve bracketing and reuse structure across parameter changes. Options control transients, stride, escape/work limits. mapdiagram resets the initial state for each parameter value; it is a sampled orbit diagram, not branch continuation or proof of chaos. See examples/discrete-maps."},
        {"interp1|deval","Evaluate sampled or ODE solutions between output times.","vector y=interp1(x,values,queries); matrix p=deval(s,queries);","interp1 is piecewise linear. New ODE solutions retain native integrator dense polynomials when enabled; legacy sampled solutions use their documented sample/RHS Hermite path. Queries must lie inside the solved interval."},
        {"trapz|cumtrapz|diff|divergence|laplacian|integral","Numerical calculus on samples or functions.","real area=trapz(x,y); real a=integral(f,0,1);","Sampled differences/gradients obey spacing and shape checks. A nonempty second derivative/laplacian requires at least three samples along every differentiated axis. Generic integral currently uses the existing supported callback contract. Native optimizer/ODE/map callbacks are separate compiled interfaces."},
        {"figure|close|clf|dock|undock|tilefigures","Create, name, arrange and clear figures.",R"(figure(1,"Name","Results","NumberTitle","off"); tilefigures("studio",1,2);)","Figures can be docked in Studio or undocked and tiled on the desktop. close(\"all\") closes figures. Save whole figures or individual subplots as PNG/JPEG/SVG through their controls."},
        {"subplot|plot|plot2|plot3","Plot real samples or projected Pentarnion vectors/trajectories.",R"(subplot(2,1,1); plot(t,y); plot3("i","j","k",p,q);)","plot handles component time series/real coordinates; plot2/plot3 select canonical component axes for Pentarnion vectors or trajectories. Arrows distinguish vectors. Each subplot supports zoom, pan, reset, sample markers, multiple removable data tips and export."},
        {"title|xlabel|ylabel|zlabel|caption","Annotate the current subplot.",R"(title("Trajectory"); xlabel("$t$"); caption("$p(t)$");)","Supported LaTeX math is rendered natively. Annotation strings belong to the active figure/subplot and are included in image/SVG exports."},
        {"save|load","Save or restore workspace data.",R"(save("workspace.pws","A","p"); load("workspace.pws");)","Paths resolve relative to the source/project data directory. Console load introduces saved names; scripts declare typed targets before load. Workspace files contain data, not arbitrary executable filesystem commands."},
        {"readmatrix|writematrix|csvread|csvwrite|xlsread|xlswrite","Read and write numeric CSV/XLSX data.",R"(matrix A=readmatrix("data.csv"); writematrix(A,"results.xlsx");)","CSV uses native parsing; XLSX uses xlsxio. Optional sheet names apply to XLSX. Only the documented numeric table formats are accepted; this is not an Excel automation interface."},
        {"assert|error|warning","Report conditions, errors and warnings.",R"(assert(x>0,"positive x required"); warning("check convergence");)","error and failed assertions stop the request. Warnings print in red without stopping it. Ordinary output stays black. Click a source diagnostic to navigate to its line."},
        {"ctrl+c|interrupt","Cancel pending input or request execution cancellation.","Press Ctrl+C with no selected console text.","Unfinished input is abandoned and a fresh prompt is shown. During work Ctrl+C requests cancellation; a native library call may finish its documented cancellation unit first. With selected text Ctrl+C copies it."}
        ,{"lyapunov|stability|poincare|recurrence","Analyze native ODE/map dynamics.",R"(record L=lyapunov(model,initial,options(t1=50,qr_step=.5));)","Generated tangent equations and real QR give finite-time spectra; transient/time/QR refinement is required. Poincare uses localized native event data. Stability checks residuals and real-coordinate eigenvalues. Finite estimates do not certify chaos. See examples/chaos-analysis and specs/chaos_v0_2.txt."}
        ,{"ensemble","Evaluate independent cached native map experiments.",R"(record E=ensemble(map,initial_rows,options(iterations=100,threads=4));)","Rows are independent real-coordinate initial states. Shared workers, deterministic task identities and separate failed/escaped statuses preserve native body reuse. This is a bounded map ensemble, not general parfor or ODE ensembles. See examples/parallel-map-ensembles."}
        ,{"pdesolve|pdecoeff","Solve one-dimensional real/Pentarnion reaction-diffusion equations.",R"(record u=pdesolve(reaction,x,u0,options(method="fd",boundary="periodic",diffusion=.1,t1=1,time_step=.001));)","Reaction signature (state,real time,real space[,fixed parameters]) is compiled/cached. fd uses uniform centered differences; fem uses P1 consistent mass and a nodal-interpolant reaction load. Periodic, constant Dirichlet and zero-flux Neumann boundaries; checked explicit RK4 limits. All five coefficients retained. pdecoeff(u,0..4) selects a real field. See examples/pdes-and-geometry and PDE_GEOMETRY_GUIDE.txt."}
        ,{"surf|imagesc|contour|isosurface|curvegeometry","Plot real scalar fields and inspect sampled real curves.",R"(imagesc(x,y,Z); surf(x,y,Z); contour(x,y,Z,[.5,1]); isosurface(x,y,z,V,level);)","Z rows follow y and columns x. Volume samples use x-fastest order, y rows per z slice. Geometry kernels retain physical vertices/scalars; native PNG/JPEG/SVG exports and mesh data tips are supported. curvegeometry returns sampled arc/tangent/normal/curvature estimates. Native chart metrics/geodesics and tagged surface geometry use separate explicit APIs: help chartgeometry; help meshplane."}
        ,{"fft|ifft|pwelch|autocorr|findpeaks","Analyze real sampled signals.",R"(record F=fft(signal); record P=pwelch(signal,options(fs=100));)","FFT uses explicit split real/imaginary arrays, unscaled forward and1/N inverse. Supported lengths are2/3/5-smooth. Welch returns one-sided density with stated Hann window normalization. Correlations/peaks have documented finite-sample conventions. See examples/signal-analysis and specs/science_data_v0_2.txt."}
        ,{"variance|stddev|covariance|quantile|histogram|bootstrap|normpdf|normcdf|norminv","Compute statistics and seeded uncertainty summaries.",R"(record B=bootstrap(data,options(statistic="mean",replicates=200,seed=7));)","Sample/population denominators, probability/domain checks, quantile conventions and numeric-data bootstrap assumptions are explicit. Bootstrap intervals require an appropriate sampling model. See examples/statistics and specs/science_data_v0_2.txt."}
        ,{"sym|symdiff|symsubs|symsimplify|symnumeric|symtext","Work with exact rational formal expressions.",R"HELP(record e=sym("(a*b)*c-a*(b*c)"); string text=symtext(e);)HELP","The native exact expression tree preserves ordered/nonassociative multiplication grouping. Differentiation/substitution do not invent commutativity or algebra identities. This is a bounded formal rational backend, not a general CAS or symbolic PDE solver. See examples/symbolic-algebra."}
        ,{"analysisrecord|saveanalysis|loadanalysis","Save reproducible data-only research records.",R"(record r=analysisrecord("experiment",data,settings); saveanalysis("experiment.json",r);)","Record schemas, numerical settings, source/cache/backend identities and hashes support provenance. Loading validates data without executing source. See examples/reproducible-analysis; records do not certify mathematical conclusions."}
        ,{"evolve","Search with native genetic and evolutionary optimizers.",R"(record r=evolve(objective,initial,options(algorithm="jde",lower=-5,upper=5,seed=7));)","Algorithms jde,ide,cmaes,ga,nsga2 use pagmo2; native objective bodies are cached while parameters change. Bounded coordinates, log coordinates, budgets, shared workers and multiobjective Pareto output are explicit. Some upstream generations are serial. See examples/evolutionary-optimization and specs/evolution_v0_2.txt."}
        ,{"outputfcn|outputevery|iterationinfo","Monitor iterative optimization and draw live fitted models.",R"(function integer monitor(matrix x,record info=iterationinfo(),string state="iter"){return 0;} record r=minimize(objective,initial,options(OutputFcn=monitor));)","OutputFcn receives copied physical coordinates, available statistics and init/iter/done states. Return1 for clean stop. Ceres reports iterations; evolution generations; NLopt/root backends evaluation events. UI observation code may plot; numerical objective/residual/event bodies stay native. OutputEvery samples delivered events; no hidden objective evaluations. See examples/iteration-callbacks."}
        ,{"searchset|searchinterval|pentdirections|discoverplan","Declare bounded search domains and count native ODE candidates.","record p=discoverplan(model,initial_rows,options(parameters=options(a=searchset([1,2]))));","Continuous intervals require samples/method/seed. Initial rows contain every real coordinate; Pentarnions use five. pentdirections returns242 signed normalized directions. See specs/research_frontier_v0_2.txt and examples/native-discovery."}
        ,{"discover|odeensemble|discoverstatus|experimentrun","Run, checkpoint and replay independent native ODE experiments.","record r=odeensemble(model,initial_rows,options(threads=4)); record one=experimentrun(model,r,1);","One immutable compiled RHS/Jacobian is shared; each solver owns its workspace. Runtime parameters do not recompile bodies. Checkpoints skip completed tasks. Finite-time evidence labels are candidates, not proofs of chaos/boundedness. Replay keeps originalgamma metadata and all real coordinates."}
        ,{"exportexperiment","Save selected experiment plots with a native headless renderer.","record images=exportexperiment(model,r,options(ids=[1,3],kinds=\"series,trajectory2\",directory=\"plots\"));","Choose ids OR top_n with deterministic scoring. Control axes,dimensions,DPI,image/disk limits. enabled=0 creates no files. Separate hash-checked exportledgers permit resume; numerical results survive individual plot failures. Native bitmap output retains UTF8 metadata; GUI exports provide math typography."}
        ,{"periodicorbit|continueequilibrium|continueperiodic","Refine autonomous cycles and follow branches natively.","record r=periodicorbit(model,initial,options(period=6.3));","Shooting uses a phase condition, generated tangent equations and Floquet multipliers. Pseudo-arclength tracks equilibrium/periodic branches. Bifurcation markers remain sampled candidates until refined; inspect closure/neutral/error/status fields. See examples/periodic-orbits."}
        ,{"pdesolve2|pdeslice","Solve and inspect real or five-component fields on a 2D grid.","record f=pdesolve2(reaction,x,y,initial,options(integrator=\"imex_euler\",threads=4)); matrix frame=pdeslice(f,2);","Initial shape is ny-by-nx, flattened x-fastest. RK4 or first-order implicit-diffusion/explicit-reaction IMEX Euler; periodic,constantDirichlet,homogeneousNeumann. Native shared workers also support 1D FD/P1-FE. Actual worker counts are reported. See examples/pde-patterns and parallel-pdes."}
        ,{"chartgeometry|geodesic","Compute native chart metrics, curvature, geodesics and transport.","record g=chartgeometry(embedding,[0.8,0.4]); record p=geodesic(embedding,[0.8,0.4],[0.1,0.2]);","Cached AD2 uses all2..5embeddingcoordinates. Induced Euclidean or explicitly supplied SPD metric; codimension-aware projectors/mean vector. Geodesics are chart-local RK4. Singular metrics fail; no metric is inferred from Pentarnion multiplication. See examples/differential-geometry."}
        ,{"sensitivity","Run native Morris or Sobol experiments.","record s=sensitivity(model,lower,upper,options(method=\"sobol\",samples=4096,seed=42,threads=4));","Compiled scalar-real models, independent uniform coordinate ranges, deterministic matched samples and optional matched-row bootstrap. Estimates are not clipped. State assumptions and inspect variance/status. modelsensitivity adds explicit native ODE/map/PDE summaries with its own documented solver settings. See examples/global-sensitivity."}
        ,{"profilefit|fitbootstrap|multistartfit","Refit native models for profiles, bootstrap and multiple starts.","record r=profilefit(model,theta0,x,y,2,grid,options(objective=\"gaussian_known_variance\",noise_variance=0.04));","Existing native Ceres backend, scalar-real curve output, parametercoords first/x last. Noisevariance is explicit for likelihooddeviance; SSE profiles are descriptive. Bootstrap pairs/centeredresidual/circularblocks yields fitted-mean bands, with rank/failure masks. Completed-task checkpoints and shared CPU limits apply. See examples/native-inference-and-refits."}
        ,{"symexpand|symcoeff|sympentdiff|sympentsubs|sympentnumeric|sympenttext|sympentcode","Expand exact ordered Pentarnion polynomials.","record e=symexpand(\"(p*q)*p\",options(pentarnions=\"p,q\",gamma=\"1/2\"));","Published normalized table, exact rational/radical coefficients and explicit central-real variables. No reassociation/cancellation assumptions. Numeric context must match recordgamma. Generated native source is inspectable and checked. Existing formal sym APIs are compatible. See examples/exact-pentarnion-symbolics."}
        ,{"daesolve","Solve local index-one implicit systems with native IDAS.","record s=daesolve(residual,y0,yp0,options(algebraic=[0,1],initialization=\"consistent\"));","Residual inputs t,y,yp then fixedparameters; real/Pentarniongroups retain everycoordinate. Compiler AD forms the Newton Jacobian. Explicit mask and localrankcheck; no general indexreduction. Native events/resets restart consistently; saltation/adjoints are separate. See examples/implicit-daes-and-hybrid-events."}
        ,{"mechanics","Simulate regular Newtonian, Lagrangian or Hamiltonian systems natively.","record s=mechanics(model,q0,second0,options(form=\"hamiltonian\",method=\"midpoint\"));","Secondinput is velocity for Newton/L, momentum for H. Positive diagonal Newtonmasses; position-only Verlet; generated regular Euler-Lagrange AD2; canonical H gradient/analytic-Hessian midpoint. Reject singular/method-incompatible cases. No automatic constraints/units claim. See examples/native-mechanics."}
        ,{"ndarray|complexarray|pentarray|ndinfo|ndvalues|ndget|ndset|ndreshape|ndpermute|ndslice","Construct and index versioned N-D arrays and fields.","record A=ndarray(values,[2,3,4]); record entry=ndget(A,[1,2,3]);","Immutable records, up to8axes, column-major order, explicit1/2/5realcoordinatekind. ndget returns a one-element NDrecord; ndvalues exposes coordinates. Preserve one-based indexing and named physicalaxes. Existing2D operators remain compatible; use nd*operations for NDrecords. See examples/multidimensional-fields."}
        ,{"ndadd|ndsub|ndmul|nddiv|ndmatmul|ndconj|ndabs|ndreal|ndimag|ndcoeff|ndfft|ndifft|ndinterp|ndmap|ndplot","Operate on native real/complex/Pentarnion N-D fields.","record F=ndfft(A,1); record B=ndmap(A,native_function);","Broadcast aligns axes fromaxis1; non-singleton physicalmetadata must match. ndmatmul currentlyrank2. ArbitrarysupportedFFTlengths use nativeBluestein/radix2; Fouriercomplexunit is distinct fromalgebrai. Extract Pentarnioncoefficients first. Transformedaxes refuse physicalplot/interp. ndmap uses cachednative scalarcallbacks/sharedCPUbudget."}
        ,{"hold|legend|plotstyle|xlim|ylim|zlim|axis|linkaxes|exportgraphics","Configure publication plots and physical image dimensions.","hold(\"on\"); legend(\"data\",\"model\"); xlim([0,10]); exportgraphics(\"figure.pdf\",options(width_cm=16,height_cm=10));","Styles/limits preserve numerical samples; 2Dlinkedaxes and nativevectorPDF have documentedbounds. GUI PNG/JPEG/SVG/PDF export; headless exportgraphics supportsPNG. Draw Tile layouts with spans/dividers and save versioned arrangements. See examples/publication-plots."}
        ,{"animatefield|animationframe|playanimation|exportframes|exportvideo","Play retained field samples and save selected frames/video.","animatefield(field,options(component=0,fps=15)); record v=exportvideo(field,\"field.avi\",options(fps=15,max_frames=120));","No simulation runs on the GUI thread. Component0..4, fixed colorscale, explicit frame/range/resolution/disk budgets. PNGframes and nativeuncompressedAVI are opt-in; AVIislarge and fixed displayFPS is distinct fromphysicalsampletimes. No externalcodec/Pythondependency. See examples/field-animation."}
        ,{"graph|digraph|graphinfo|graphcomponents|components|shortestpath|spanningtree|toposort|centrality|graphlaplacian|graphadjacency|graphlayout|graphcycle|plotgraph","Use native directed/undirected weighted graphs.","record G=graph([1,2;2,3],options(n=4)); record path=shortestpath(G,1,3);","Stableone-basednode/edgeIDs, explicitweight/negativecycle semantics and bounded nativealgorithms. graphcomponents is unambiguous; optionalcomponentsalias remains shadowable by existingarrayvariables. WholePentarnions are not orderedpathcosts. See examples/graph-theory."}
        ,{"provenance|researchrecord","Capture automatic scientific identity separately from execution metadata.","record r=researchrecord(\"experiment\",data,settings); saveanalysis(\"result.json\",r);","Records include source/import/native/backend hashes, algebra/gamma/language/precision; paths/thread/timing metadata are separate. Typed data-only persistence remains atomic; hashes are integrityevidence, not signatures. Existing analysisrecordv1 remains compatible. See specs/research_frontier_v0_2.txt."}
        ,{"pdeensemble|pdeensemble2|pderun|pdeparams|pdesettings|pdereplay","Run and replay independent native PDE experiments.",R"(record b=pdeensemble(reaction,x,initial_rows,options(threads=4,retain=[1])); record f=pderun(b,1);)","Paired broadcasts or explicit Cartesian catalogues, cached reactions, immutable per-run gamma and shared outer workers. Raw real coefficients prevent context relabelling. Selected full fields and completed-task checkpoint/replay are bounded. See examples/parallel-pde-experiments."}
        ,{"meshplane|meshsphere|meshcylinder|meshcircle|paramesh|trimesh|meshinfo|meshtransform|meshrefine|meshplot|meshread|meshwrite|lineplane|raysphere","Construct, inspect and display real surface geometry.",R"(record S=meshsphere(1,options(refinements=2)); meshplot(S);)","Tagged triangular meshes retain2..5 real coordinates. Native parametric embeddings preserve all Pentarnion coefficients. Explicit Euclidean geometry, projected plots, strict data-only mesh files and real intersections. See examples/real-geometry."}
        ,{"dform|formfield|wedge|exteriord|hodge|laplacebeltrami","Evaluate real oriented differential forms and chart operators.",R"(record a=dform(2,1,[1,0],options(metric=[4,0;0,9])); record b=hodge(a);)","Explicit real SPD metric/orientation, increasing-index form coefficients, native analytic coefficient jets and checked degree/domain limits. Derivatives unavailable from retained jets fail. See examples/differential-forms."}
        ,{"surfaceheat|surfacecoeff","Solve diffusion/reaction on tagged real surface meshes.",R"(record s=surfaceheat(mesh,initial,options(t1=.1,time_step=.001,threads=4)); matrix c=surfacecoeff(s,0);)","Consistent P1 mass, implicit diffusion/explicit native reaction, all five field coefficients and deterministic shared-budget assembly. Sparse factor/solve calls remain serial and reused. See examples/surface-diffusion."}
        ,{"graphsparse|graphgen|savegraphlayout|loadgraphlayout","Create sparse graph operators, seeded generators and reproducible layouts.",R"(record G=graphgen("path",8); record L=graphsparse(G,options(kind="laplacian"));)","Canonical CSC without dense staging. Stable IDs and explicit directed orientation; interactive graph views use the existing figure canvas. Layout import validates topology/labels/weights before applying. See examples/interactive-graphs."}
        ,{"networksolve|networkcoeff","Integrate coupled native real/Pentarnion node dynamics.",R"(record s=networksolve(local_model,G,initial_rows,options(t1=1,threads=4)); matrix node=networkcoeff(s,1,1);)","One native cached local ODE body, all coordinates retained, real incoming-edge diffusion and shared CPU limits. Coefficients and Euclidean synchronization have explicit layouts. Inspect method/stats and refine time steps. See examples/native-networks."}
        ,{"verifyexperiment|verifyrun","Recheck selected ODE candidates using native longer/tighter tiers.",R"(record v=verifyexperiment(model,experiment,[1,3],options(horizons=[20,40],lyapunov=1));)","Preserve original IDs/inputs/settings, full physical-state recurrence and explicit tangent/method/QR/tier flags. Optional autonomous shooting/Floquet. Finite-time candidate evidence is not proof of chaos or global boundedness. verifyrun replays one evidence row. See specs/verification_v0_2.txt."}
        ,{"modelsensitivity","Analyze sensitivity of native ODE, map and PDE summaries.",R"(record r=modelsensitivity(model,[0],[1],options(initial=[0],parameters=options(rate=0.0),method="morris",samples=4));)","Compiled native solvers on the shared pool; explicit flat parameter coordinates, runtime initial/solver data, independent-uniform Morris/Sobol samples and buffer forecasts. No failed-solve imputation. Discrete sampled summaries require refinement. See examples/solver-summary-sensitivity."}
        ,{"constrainedmechanics","Integrate regular holonomic mechanics with native SHAKE/RATTLE.",R"(record s=constrainedmechanics(@potential,@constraints,q0,v0,options(method="rattle",mass=1));)","Constant real SPD mass, autonomous separable potential/constraints, compiler-generated gradients/Hessians, explicit initial reject/project policy and sampled constraint/energy/multiplier diagnostics. No generic index reduction or nonholonomic formulation. See examples/constrained-mechanics."}
        ,{"quantity|unitconvert|unitadd|unitsub|unitmul|unitdiv|unitpow|unitvalues|unitcompatible|unitinfo","Use explicit real SI quantities and dimensional checks.",R"(record distance=quantity([100,200],"cm"); record metres=unitconvert(distance,"m"); matrix values=unitvalues(metres);)","Seven bounded integer SI dimensions; elementwise equal shapes/scalar expansion. Add/convert require compatible dimensions. Native numeric/AD operators never strip records implicitly. Affine temperatures and whole-Pentarnion quantities reject. See specs/physical_quantities_v0_2.txt."}

        ,{"hybridsolve|hybridval|hybridadjoint","Solve native hybrid events with explicit sensitivities and terminal adjoints.",R"(record s=hybridsolve(model,@event,@reset,initial,options(...));)","One scalar transverse event and native reset/RHS/terminal objective; fixed-time saltation differs from moving-event derivatives. Epoch interpolation never crosses jumps. Cold compilation is excluded from numerical timing. See specs/hybrid_saltation_v0_2.txt and examples/hybrid-event-sensitivities."}
        ,{"femsolve|femplot","Solve bounded real elliptic equations with native MFEM H1 elements.",R"(record s=femsolve(mesh,@forcing,options(order=4)); femplot(s);)","Tagged real R2 triangles, orders1..4, positive diffusion/nonnegative reaction and anchored boundary components. Authoritative high-order DOFs and sampled display mesh remain separate. Inspect actual residual/converged/error fields. Serialized execution shares Studio's CPU budget. See examples/high-order-finite-elements."}
        ,{"refinebifurcation","Refine native fold, Hopf and period-doubling numerical candidates.",R"(record b=refinebifurcation(model,initial,options(kind="hopf",parameter="mu",parameters=options(mu=0)));)","Augmented equations preserve full state/parameter coordinates. Native AD2 equilibrium correctors and explicit centered-difference native-flow flip correctors have distinct reported semantics. Simple-mode/transversality/refinement checks do not establish cubic criticality or a certified bifurcation. See examples/bifurcation-point-refinement."}
        ,{"saveexperiment|loadexperiment|experimentinfo|experimentsource","Save and inspect typed data with exact source snapshots.",R"(saveexperiment("run.json",result); record info=experimentinfo("run.json");)","Versioned data-only bundles validate hashes, templates and algebra context; loading never executes source. Current invocation/import bytes are included; prior console history and external artifact payloads are not. Artifact manifests use physically jailed project paths. See examples/experiment-bundles."}
        ,{"thirdderivative","Evaluate an analytic native third derivative in three directions.",R"(record d=thirdderivative(@objective,[1,2],[1,0],[0,1],[1,1]);)","Returns values and D3f[u,v,w] from one cached hyperdual3 evaluation. Directions cover complete active real coordinates, including all five coefficients per Pentarnion. Explicit groups are preserved; no full tensor or finite-difference mode. Existing first/second derivatives remain compatible. See examples/native-third-derivatives."}
    };return data;
}
inline std::string lower(std::string_view text){std::string out(text);for(char&c:out)if(c>='A'&&c<='Z')c+=('a'-'A');return out;}
inline bool alias(std::string_view names,std::string_view topic){std::string key="|"+std::string(names)+"|";return key.find("|"+std::string(topic)+"|")!=std::string::npos;}
inline std::optional<std::string> lookup(std::string_view topic) {
    const auto key=lower(topic);
    if(key=="topics") {std::string out="HELP TOPICS - use help name or lookfor words\n";for(const auto& e:entries())out+=std::string(e.names)+" - "+std::string(e.summary)+"\n";return out;}
    for(const auto& e:entries())if(alias(e.names,key))return std::string(topic)+" - "+std::string(e.summary)+"\nSyntax: "+std::string(e.usage)+"\n"+std::string(e.details)+"\nSee also: help topics; lookfor \"words\"; language.txt.";
    return {};
}
inline std::string search(std::string_view query) {
    const auto key=lower(query);std::string out="LOOKFOR "+std::string(query)+"\n";std::size_t hits=0;
    for(const auto& e:entries())if(lower(std::string(e.names)+" "+std::string(e.summary)+" "+std::string(e.details)).find(key)!=std::string::npos){out+=std::string(e.names)+" - "+std::string(e.summary)+"\n";++hits;}
    if(!hits)out+="No matching topics. Use help topics for the complete catalogue.";
    return out;
}
}
